    "guides": [
      "まず「冠を載せる場面」に目を置いてください。細部を読む前に、ここが画面の中でどれくらい強く見えるかをつかみます。",
      "次に、中央から左右の群像へ視線を動かします。目を動かすことで、人物・形・空間がどうつながっているかを確かめます。",
      "最後に「豪華な赤と金」に注目します。人物の身振りと舞台のような構図を見る。実物では近くと少し離れた位置の両方から見比べてください。"
    ]
