      "次に、顔から作業する手へ視線を動かします。目を動かすことで、人物・形・空間がどうつながっているかを確かめます。",
      "最後に「静かな光」に注目します。窓からの光と、静かな空間の密度を見る。実物では近くと少し離れた位置の両方から見比べてください。"
