      "次に、海から岸辺へ視線を動かします。目を動かすことで、人物・形・空間がどうつながっているかを確かめます。",
      "最後に「青のゆらぎ」に注目します。筆触の方向と色の強さを、近くと遠くで見比べる。実物では近くと少し離れた位置の両方から見比べてください。"
